package com.kitchenos.connect.control;
import org.junit.Test;import static org.junit.Assert.*;
public class WaterHeatingTest {
 private ControlState state(){ControlState s=new ControlState();s.connected=s.foreground=s.rootVerified=s.ownRun=s.coverVerified=true;s.potCheck.closedInterlock();s.state=1;s.samples=5;s.error=0;s.coverOpen=0;s.pot=1;s.statusAt=s.infoAt=1000;s.statusSequence=6;s.acceptedCommandStatusSequence=5;s.acceptedCommandSequence=2;s.temperature=60;return s;}
 private WaterHeating run(){WaterHeating w=new WaterHeating();w.begin(true,60,2);return w;}
 @Test public void reachesOnlyOnPostAckFreshStatus(){WaterHeating w=run();ControlState s=state();assertFalse(w.shouldLower(s,"info",1000));s.statusSequence=5;assertFalse(w.shouldLower(s,"status",1000));s.statusSequence=6;assertTrue(w.shouldLower(s,"status",1000));w.lowering(3,1000);assertFalse(w.shouldLower(s,"status",1000));assertTrue(w.loweringInFlight());assertFalse(w.loweringTimedOut(4000));assertTrue(w.loweringTimedOut(4001));w.lowered(1100);assertEquals("Ziel erreicht · Temperatur halten",w.status(s));s.acceptedCommandSequence=3;s.acceptedCommandStatusSequence=6;s.statusSequence=7;s.statusAt=s.infoAt=21099;assertFalse(w.observe(s,"status",21099));s.statusAt=s.infoAt=21100;s.statusSequence=8;assertTrue(w.observe(s,"status",21100));s.stopping=true;assertTrue(w.status(s).contains("Stoppen"));s.stopping=false;s.idleConfirmed=true;s.ownRun=false;assertEquals("",w.status(s));}
 @Test public void staleMeasurementNeverCompletes(){assertFalse(run().shouldLower(state(),"status",1500));ControlState s=state();s.infoAt=-1;assertFalse(run().shouldLower(s,"status",1000));}
 @Test public void noStartOrAckNoCompletion(){ControlState s=state();s.acceptedCommandSequence=1;assertFalse(run().shouldLower(s,"status",1000));s.acceptedCommandSequence=2;s.pendingAction="START";assertFalse(run().shouldLower(s,"status",1000));s.pendingAction="";s.ownRun=false;assertFalse(run().shouldLower(s,"status",1000));}
 @Test public void stopFaultAndDisconnectCancel(){for(String e:new String[]{"closed","stopping","stopped"}){WaterHeating w=run();assertFalse(w.observe(state(),e,1000));assertFalse(w.active());}ControlState s=state();s.error=1;WaterHeating w=run();assertFalse(w.observe(s,"status",1000));assertFalse(w.active());}
 @Test public void missingPotAndOpenLidNeverComplete(){ControlState s=state();s.coverOpen=1;assertFalse(run().shouldLower(s,"status",1000));s.coverOpen=0;s.potVerified=true;s.pot=0;assertFalse(run().shouldLower(s,"status",1000));}
 @Test public void belowTargetAndInvalidReading(){ControlState s=state();for(int t:new int[]{0,34,59,251}){s.temperature=t;assertFalse(run().shouldLower(s,"status",1000));}}
 @Test public void otherModesAndRestartNeverAutoStart(){WaterHeating w=run();w.begin(false,60,3);assertFalse(w.observe(state(),"status",1000));assertEquals("",w.status(state()));}
 @Test public void timeoutIsNotSuccess(){WaterHeating w=run();ControlState s=state();s.naturalCompletion=true;s.stopReason="Kochzeit beendet";assertFalse(w.observe(s,"stopping",1000));s.idleConfirmed=true;s.ownRun=false;assertEquals("Zeitlimit · Ziel nicht bestätigt",w.status(s));w.clearResult();assertEquals("",w.status(s));}
 @Test public void boundedHeatOnlyCommand(){ControlValues v=ControlValues.water(95);assertTrue(v.waterHeating);assertEquals("START_MANUAL 600 95 0 POT_CONFIRMED",v.command("START",true));assertFalse(new ControlValues(30,60,0,false,true).waterHeating);}
 @Test public void holdNeedsConfirmedCommandAndFreshStatus(){WaterHeating w=run();ControlState s=state();w.lowering(3,1000);w.lowered(1100);s.statusAt=s.infoAt=21100;assertFalse(w.observe(s,"status",21100));s.acceptedCommandSequence=3;s.pendingAction="APPLY";assertFalse(w.observe(s,"status",21100));s.pendingAction="";assertFalse(w.observe(s,"status",21601));assertFalse(w.holdTimedOut(26100));assertTrue(w.holdTimedOut(26101));s.ownRun=false;assertFalse(w.observe(s,"status",21100));}
 @Test public void overheatGuardRequiresFreshContinuousSamples(){WaterHeating w=run();ControlState s=state();w.lowering(3,1000);w.lowered(1100);s.temperature=66;assertFalse(w.tooHot(s,"status",1000));s.statusAt=s.infoAt=31001;assertFalse(w.tooHot(s,"status",31001));s.temperature=70;assertTrue(w.tooHot(s,"status",31001));s.temperature=60;assertFalse(w.tooHot(s,"status",31001));}
}
